import { Container, getContainer } from "@cloudflare/containers";
import type { DurableObjectNamespace } from "cloudflare:workers";

export interface Env {
  MIGHTY_AGENT_CONTAINER: DurableObjectNamespace<MightyAgentContainer>;
}

export class MightyAgentContainer extends Container {
  defaultPort = 3000;
  sleepAfter = "15m";
  enableInternet = true;
  envVars = {
    NODE_ENV: "production",
    PORT: "3000",
    LEMON_AI_PATH: "/app",
  };

  async fetch(request: Request): Promise<Response> {
    // Ensure the application server has started and is listening on the default port.
    await this.startAndWaitForPorts();

    const url = new URL(request.url);
    if (url.pathname === "/__container_health") {
      return new Response(
        JSON.stringify({ status: "ok" }),
        { headers: { "content-type": "application/json" } },
      );
    }

    return this.containerFetch(request);
  }

  override onStart(): void {
    this.renewActivityTimeout();
  }
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/__health") {
      return new Response("ok", { headers: { "content-type": "text/plain" } });
    }

    if (url.pathname === "/") {
      url.pathname = "/frontend/index.html";
      return Response.redirect(url.toString(), 302);
    }

    const container = getContainer(env.MIGHTY_AGENT_CONTAINER, "primary");
    return container.fetch(request);
  },
};
